<script setup>
import { computed, ref } from 'vue'
import { state, resolveException } from '../data/store'
const filter = ref('All')
const visible = computed(()=>filter.value==='All'?state.exceptions:state.exceptions.filter(e=>e.status===filter.value))
</script>
<template>
  <div class="p-5 lg:p-8"><div><h2 class="text-2xl font-black">Exception Center</h2><p class="mt-1 text-sm text-slate-500">Central place for cancellations, missing items, substitutions, delays and delivery problems.</p></div>
    <section class="mt-6 grid gap-4 md:grid-cols-4"><div class="rounded-2xl border border-slate-200 bg-white p-5"><p class="text-xs text-slate-500">Total Exceptions</p><p class="mt-3 text-2xl font-black">{{ state.exceptions.length }}</p></div><div class="rounded-2xl border border-slate-200 bg-white p-5"><p class="text-xs text-slate-500">Open</p><p class="mt-3 text-2xl font-black text-orange-500">{{ state.exceptions.filter(e=>e.status==='Open').length }}</p></div><div class="rounded-2xl border border-slate-200 bg-white p-5"><p class="text-xs text-slate-500">Investigating</p><p class="mt-3 text-2xl font-black text-blue-500">{{ state.exceptions.filter(e=>e.status==='Investigating').length }}</p></div><div class="rounded-2xl border border-slate-200 bg-white p-5"><p class="text-xs text-slate-500">Resolved</p><p class="mt-3 text-2xl font-black text-emerald-600">{{ state.exceptions.filter(e=>e.status==='Resolved').length }}</p></div></section>
    <section class="mt-6 rounded-2xl border border-slate-200 bg-white p-6"><div class="flex flex-wrap justify-between gap-3"><div><h3 class="font-bold">Operational Issues</h3><p class="mt-1 text-xs text-slate-500">Resolve issues and keep a record for supplier performance analysis.</p></div><div class="flex gap-2"><button v-for="f in ['All','Open','Investigating','Resolved']" :key="f" @click="filter=f" class="rounded-lg px-3 py-2 text-xs font-bold" :class="filter===f?'bg-[#1595B6] text-white':'bg-slate-100 text-slate-500'">{{ f }}</button></div></div><div class="mt-5 space-y-3"><div v-for="e in visible" :key="e.id" class="rounded-2xl border border-slate-100 p-5"><div class="flex flex-col gap-3 md:flex-row md:items-start md:justify-between"><div><div class="flex flex-wrap items-center gap-2"><p class="font-black">{{ e.type }}</p><span class="rounded-full bg-slate-100 px-2 py-1 text-[10px] font-bold">{{ e.order }}</span><span class="rounded-full px-2 py-1 text-[10px] font-bold" :class="e.severity==='High'?'bg-red-50 text-red-600':e.severity==='Medium'?'bg-orange-50 text-orange-600':'bg-blue-50 text-blue-600'">{{ e.severity }}</span></div><p class="mt-2 text-sm text-slate-600">{{ e.detail }}</p><p class="mt-1 text-xs text-slate-400">{{ e.supplier }}</p></div><div class="flex items-center gap-3"><span class="text-xs font-bold" :class="e.status==='Resolved'?'text-emerald-600':'text-orange-500'">{{ e.status }}</span><button v-if="e.status!=='Resolved'" @click="resolveException(e)" class="rounded-lg bg-[#E9F7FB] px-3 py-2 text-xs font-bold text-[#117E9E]">Resolve</button></div></div></div></div></section>
  </div>
</template>
